/* Measure original ice calls and grouped white masks through real SDL. */
#include <SDL.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){if(argc!=5&&argc!=7)return 1;int mode=atoi(argv[1]),ox=atoi(argv[2]),oy=atoi(argv[3]),height=21,width=61;unsigned long background=strtoul(argv[4],NULL,16);if(mode==2){width=60;height=20;}
SDL_Surface*s=SDL_CreateRGBSurfaceWithFormat(0,width,height,32,SDL_PIXELFORMAT_RGBA32);if(!s)return 2;SDL_Renderer*r=SDL_CreateSoftwareRenderer(s);if(!r)return 3;SDL_SetRenderDrawColor(r,background>>24,background>>16,background>>8,background);SDL_RenderClear(r);SDL_SetRenderDrawBlendMode(r,SDL_BLENDMODE_BLEND);
char op;int x,y,z,t,clip=0;while(scanf(" %c %d %d %d %d",&op,&x,&y,&z,&t)==5){int result=0;switch(op){case 'C':result=SDL_SetRenderDrawColor(r,x,y,z,t);break;case 'K':clip=x!=-1||y!=-1||z||t;if(clip){SDL_Rect c={x-ox,y-oy,z,t};result=SDL_RenderSetClipRect(r,&c);}else result=SDL_RenderSetClipRect(r,NULL);break;case 'L':if(mode==0||(mode==1&&!clip)||(mode==2&&clip))result=SDL_RenderDrawLine(r,x-ox,y-oy,z-ox,t-oy);break;case 'R':if(mode==0||mode==4){SDL_Rect c={x-ox,y-oy,z,t};result=SDL_RenderFillRect(r,&c);}break;case 'B':break;default:return 4;}if(result)return 5;}
if(mode==4){if(argc!=7)return 8;for(int i=0;i<2;i++){int w=i?60:61,h=i?20:21,n=w*h*4;unsigned char pixels[61*21*4];FILE*f=fopen(argv[5+i],"rb");if(!f||fread(pixels,1,n,f)!=(size_t)n)return 9;fclose(f);for(int at=0;at<n;at+=4)pixels[at]=pixels[at+1]=pixels[at+2]=255;SDL_Surface*layer=SDL_CreateRGBSurfaceWithFormatFrom(pixels,w,h,32,w*4,SDL_PIXELFORMAT_RGBA32);if(!layer)return 10;SDL_Texture*t=SDL_CreateTextureFromSurface(r,layer);if(!t)return 11;SDL_SetTextureBlendMode(t,SDL_BLENDMODE_BLEND);SDL_SetTextureScaleMode(t,SDL_ScaleModeNearest);SDL_Rect dst={0,0,w,h};if(SDL_RenderCopy(r,t,NULL,&dst))return 12;SDL_DestroyTexture(t);SDL_FreeSurface(layer);}}
unsigned char bytes[61*21*4];if(SDL_RenderReadPixels(r,NULL,SDL_PIXELFORMAT_RGBA32,bytes,width*4))return 6;if(fwrite(bytes,1,width*height*4,stdout)!=(size_t)width*height*4)return 7;SDL_DestroyRenderer(r);SDL_FreeSurface(s);return 0;}
